test("returns 31 days and 50.96 interest for 10000 at 6 percent from 2026-03-01 to 2026-04-01", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  assert.deepEqual(actual, { days: 31, interest: 50.96 });
});

test("returns 29 days and 47.67 interest in a leap year using divisor 365", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-01",
    endDate: "2028-03-01"
  });
  assert.deepEqual(actual, { days: 29, interest: 47.67 });
});

test("returns 0 days and 0.00 interest when the start date and end date are the same", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-03-01"
  });
  assert.deepEqual(actual, { days: 0, interest: 0.00 });
});
